inline FScriptArrayHelper ComputedArray(UObject* O,const TCHAR* Name){auto* P=FindFProperty<FArrayProperty>(O->GetClass(),Name);return FScriptArrayHelper(P,P->ContainerPtrToValuePtr<void>(O));}
inline int32 ComputedArrayLast(UObject* O,const TCHAR* Name){auto A=ComputedArray(O,Name);return A.Num()?*reinterpret_cast<int32*>(A.GetRawPtr(A.Num()-1)):MIN_int32;}
inline void ComputedArrayManual(UObject* O,const TCHAR* Name){auto A=ComputedArray(O,Name);A.EmptyValues();const int32 I=A.AddValue();*reinterpret_cast<int32*>(A.GetRawPtr(I))=777;}
inline bool ComputedContainers(UObject* O){auto* C=O->GetClass();auto* M=FindFProperty<FMapProperty>(C,TEXT("ScoresDefault"));auto* S=FindFProperty<FSetProperty>(C,TEXT("TagsDefault"));auto* E=FindFProperty<FMapProperty>(C,TEXT("EnumDefault"));auto* N=FindFProperty<FMapProperty>(C,TEXT("NamesDefault"));auto* V=FindFProperty<FArrayProperty>(C,TEXT("VectorsDefault"));if(!M || !S || !E || !N || !V)return false;
 auto Ratios=ComputedArray(O,TEXT("Ratios"));if(Ratios.Num()!=1 || *reinterpret_cast<double*>(Ratios.GetRawPtr(0))!=1.2345678901234567)return false;
 FScriptMapHelper Map(M,M->ContainerPtrToValuePtr<void>(O));FString Key=TEXT("one");int32 I=Map.FindMapIndexWithKey(&Key);if(I==INDEX_NONE || *reinterpret_cast<int32*>(Map.GetValuePtr(I))!=8)return false;FScriptSetHelper Set(S,S->ContainerPtrToValuePtr<void>(O));FString Tag=TEXT("8");if(Set.Num()!=3 || Set.FindElementIndex(&Tag)==INDEX_NONE)return false;FScriptMapHelper Enums(E,E->ContainerPtrToValuePtr<void>(O));uint8 EnumKey=1;I=Enums.FindMapIndexWithKey(&EnumKey);if(I==INDEX_NONE || *reinterpret_cast<int32*>(Enums.GetValuePtr(I))!=8)return false;FScriptMapHelper Names(N,N->ContainerPtrToValuePtr<void>(O));FName Name(TEXT("ITEM_3"));I=Names.FindMapIndexWithKey(&Name);if(I==INDEX_NONE || *reinterpret_cast<int32*>(Names.GetValuePtr(I))!=5)return false;FScriptArrayHelper Vectors(V,V->ContainerPtrToValuePtr<void>(O));return Vectors.Num()==1 && *reinterpret_cast<FVector*>(Vectors.GetRawPtr(0))==FVector(5,8,3);
}


inline void ComputedManualHash(UObject* O){auto* M=FindFProperty<FMapProperty>(O->GetClass(),TEXT("ScoresDefault"));FScriptMapHelper Map(M,M->ContainerPtrToValuePtr<void>(O));Map.EmptyValues();FString Key=TEXT("manual");int32 Value=777;Map.AddPair(&Key,&Value);auto* S=FindFProperty<FSetProperty>(O->GetClass(),TEXT("TagsDefault"));FScriptSetHelper Set(S,S->ContainerPtrToValuePtr<void>(O));Set.EmptyElements();Set.AddElement(&Key);}
inline bool ComputedManualHashMatches(UObject* O){auto* M=FindFProperty<FMapProperty>(O->GetClass(),TEXT("ScoresDefault"));FScriptMapHelper Map(M,M->ContainerPtrToValuePtr<void>(O));FString Key=TEXT("manual");int32 I=Map.FindMapIndexWithKey(&Key);auto* S=FindFProperty<FSetProperty>(O->GetClass(),TEXT("TagsDefault"));FScriptSetHelper Set(S,S->ContainerPtrToValuePtr<void>(O));return Map.Num()==1 && I!=INDEX_NONE && *reinterpret_cast<int32*>(Map.GetValuePtr(I))==777 && Set.Num()==1 && Set.FindElementIndex(&Key)!=INDEX_NONE;}
